import { defineComponent, computed, h, onMounted, ref, useId } from 'vue';
import { getTextareaIds, getTextareaAriaProps } from '../lib/core';
import styles from './textarea.module.scss';

export const Textarea = defineComponent({
	name: 'Textarea',
	props: {
		label: String,
		error: String,
		helperText: String,
		required: { type: Boolean, default: false },
		id: String,
		placeholder: String,
		modelValue: String,
		defaultValue: String,
		readOnly: { type: Boolean, default: false },
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue'],
	setup(props, { emit }) {
		const fallbackId = useId();
		const textareaId = computed(() => props.id || fallbackId);
		const ids = computed(() => getTextareaIds(textareaId.value));
		const ariaProps = computed(() => getTextareaAriaProps(ids.value, props.error, props.helperText));
		const textareaEl = ref<HTMLTextAreaElement | null>(null);

		onMounted(() => {
			if (!textareaEl.value) return;
			if (props.modelValue === undefined && props.defaultValue !== undefined) {
				textareaEl.value.value = props.defaultValue;
			}
		});

		function onInput(event: Event) {
			emit('update:modelValue', (event.target as HTMLTextAreaElement).value);
		}

		return () => {
			const children: any[] = [];

			if (props.label) {
				children.push(
					h(
						'label',
						{
							for: textareaId.value,
							class: [styles.label, props.required ? styles.required : ''],
						},
						props.label,
					),
				);
			}

			children.push(
				h('textarea', {
					ref: textareaEl,
					id: textareaId.value,
					class: [styles.textarea, props.error ? styles.error : ''],
					value: props.modelValue,
					placeholder: props.placeholder,
					readonly: props.readOnly,
					disabled: props.disabled,
					'aria-invalid': ariaProps.value['aria-invalid'],
					'aria-describedby': ariaProps.value['aria-describedby'],
					onInput,
				}),
			);

			if (props.error) {
				children.push(h('span', { id: ids.value.error, class: styles.errorText }, props.error));
			} else if (props.helperText) {
				children.push(h('span', { id: ids.value.helper, class: styles.helperText }, props.helperText));
			}

			return h('div', { class: styles.textareaWrapper }, children);
		};
	},
});

export default Textarea;

@use '../../../styles/variables/colors' as *;

.textareaWrapper {
	display: flex;
	flex-direction: column;
	gap: var(--tile-textarea-label-gap, #{$spacing-1});
	width: 100%;
}

.textarea {
	display: flex;
	min-height: var(--tile-textarea-min-height, 5rem);
	width: 100%;
	border-radius: var(--tile-textarea-radius, #{$radius});
	border: var(--tile-textarea-border-width, 1px) solid var(--tile-textarea-border, #{$border});
	background-color: var(--tile-textarea-background, #{$background});
	padding: var(--tile-textarea-padding, #{$spacing-3} #{$spacing-3});
	font-size: var(--tile-textarea-font-size, #{$text-sm});
	box-shadow: var(--tile-textarea-shadow, none);
	color: $foreground;
	transition: all $transition-fast;
	outline: none;
	resize: vertical;
	font-family: inherit;
	line-height: var(--tile-textarea-line-height, #{$leading-normal});

	&::placeholder {
		color: var(--tile-textarea-placeholder, #{$muted-foreground});
	}

	&:focus {
		outline: none;
		border-color: var(--tile-textarea-focus-border, #{$ring});
		box-shadow: var(--tile-textarea-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:disabled,
	&.disabled {
		pointer-events: none;
		opacity: var(--tile-textarea-disabled-opacity, 0.5);
		cursor: not-allowed;
		background-color: var(--tile-textarea-disabled-background, #{$field-disabled});
		color: var(--tile-textarea-disabled-color, #{$foreground});
	}

	&.error {
		border-color: $destructive;
		box-shadow: var(--tile-textarea-error-shadow, none);

		&:focus {
			border-color: $destructive;
			box-shadow: var(--tile-textarea-error-focus-shadow, 0 0 0 1px #{$destructive});
		}
	}
}

.label {
	display: block;
	font-size: var(--tile-textarea-label-font-size, #{$text-sm});
	font-weight: $font-medium;
	color: $foreground;
	line-height: $leading-normal;

	&.required::after {
		content: ' *';
		color: $destructive;
	}
}

.helperText {
	font-size: var(--tile-textarea-description-font-size, #{$text-xs});
	color: var(--tile-textarea-description-color, #{$muted-foreground});
	line-height: var(--tile-textarea-description-line-height, #{$leading-normal});
}

.errorText {
	font-size: var(--tile-textarea-description-font-size, #{$text-xs});
	color: $destructive;
	line-height: var(--tile-textarea-description-line-height, #{$leading-normal});
}
